    'https://v7.gyks.cf',
    'http://101.35.133.34:8888',
    'http://103.236.91.147:8888'
];

function getArguments(open_argument, key) {
    try {
        open_argument = JSON.parse(open_argument);
    } catch (e) {
        open_argument = {
            tab: "小说",
            tone_id: "默认音色",
            server: host[0],
            sources: "全部",
            source_type: "男频",
        };
    }
    if (key) {
        return open_argument[key];
    } else {
        return open_argument;
    }
}

function setArguments(key, value) {
    const {
        source
    } = this;
    let open_argument = source.getVariable();
    open_argument = getArguments(open_argument, '');
    open_argument[key] = value;
    open_argument = JSON.stringify(open_argument);
    source.setVariable(open_argument);
    return open_argument;
}

function decrypt(Text) {
    return Text;
}

function paraForAndroid(content, sources) {
    let {
        java,
        cache,
        source
    } = this;
    let plcolor = getArguments(source.getVariable(), "plcolor");
    if (!plcolor) {
        plcolor = "#000000";
    }
    let tccolor = getArguments(source.getVariable(), "tccolor");
    if (!tccolor) {
        plcolor = "none";
    }

    const createSvg = this.createSvg.bind(this);

    return content.replace(/<p>(.*?)(?:<comment ident="([^"]*)" count="([^"]*)" \/>)?<\/p>/g,
        (match, text, url, count) => {
            if (url && count) {
                const click = 0;
                cache.putMemory(url, click);
                const encodedUrl = url;
                return `<p>${text}<img src="${createSvg(count, plcolor,tccolor,encodedUrl,sources)}"></p>`;
            } else {
                return `<p>${text}</p>`;
            }
        }
    );
}


function showCmt(url, sources) {
    let {
        java,
        cache
    } = this;

    const currentTime = Date.now();
    const click = cache.getFromMemory(url);
    let isqread = false;
    try {
        java.qread();
        isqread = true;
    } catch (e) {}
    if (click < 1 && !isqread) {
        cache.putMemory(url, click + 1);
        return;
    } else {
        try {
            java.startBrowserDp(url, sources + '段评');
        } catch (e) {
            java.startBrowser(url, sources + '段评');
        }
    }
}



function createSvg(number, color, tccolor, encodedUrl, sources) {
        var displayText = number > 99 ? "99+" : number.toString();
        var loginInfoMap = {};

        if (this.source && typeof this.source.getLoginInfoMap == 'function') {
            loginInfoMap = this.source.getLoginInfoMap() || {};
        }

        var bubbleStyle = String(getArguments(this.source.getVariable(), "pstyle") || loginInfoMap['段评气泡样式(0-4)'] || '0');
        var svg;
        if (bubbleStyle == '0') {
            svg = `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="90" viewBox="0 0 25 17" fill="none" style="color: ${color}; opacity: 1;">
                        <path d="M24 14.5v-12a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v7.528a2 2 0 0 1-.211.894l-2.065 4.13a1 1 0 0 0 .894 1.448H22a2 2 0 0 0 2-2z" stroke="currentColor" style="stroke: ${color}; stroke-opacity: 0.5; stroke-width: 1px; stroke-linejoin: round; fill: ${tccolor}; fill-opacity: 0.5;"></path>
                        <text x="13.5" y="12" text-anchor="middle" alignment-baseline="auto" font-size="10" fill="currentColor" font-family="Arial, sans-serif" font-weight="500" style="fill: ${color}; opacity: 1;">${displayText}</text>
                    </svg>`;
        } else if (bubbleStyle == '1') {
            svg = `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="90" viewBox="0 7 153 106" style="color: ${color}; opacity: 1;">
                        <path d="M 55 10 L 120 10 Q 150 10 150 40 L 150 80 Q 150 110 120 110 L 55 110 Q 25 110 25 80 L 25 75 L 3 60 L 25 45 L 25 40 Q 25 10 55 10 Z" stroke="currentColor" stroke-width="6" stroke-linejoin="round" style="stroke: ${color}; stroke-opacity: 0.5; stroke-width: 4px; stroke-linejoin: round; fill: ${tccolor}; fill-opacity: 0.5;"></path>
                        <text x="87" y="86" alignment-baseline="auto" font-family="Arial, sans-serif" text-anchor="middle" font-size="72" font-weight="500" fill="currentColor" style="fill: ${color}; opacity: 1;">${displayText}</text>
                </svg>`;
        } else if (bubbleStyle == '2') {
            svg = `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="90" viewBox="6 10 88 76" style="color: ${color}; opacity: 1;">
                        <path d="M12,12 L88,12 Q92,12 92,16 L92,68 Q92,72 88,72 L28,72 L12,84 L12,72 Q8,72 8,68 L8,16 Q8,12 12,12 Z" stroke="currentColor" stroke-width="4" stroke-linejoin="round" style="stroke: ${color}; stroke-opacity: 0.5; stroke-width: 2.5px; stroke-linejoin: round; fill: ${tccolor}; fill-opacity: 0.5;"></path>
                        <text x="50" y="60" font-family="Arial, sans-serif" text-anchor="middle" font-size="45" fill="currentColor" font-weight="500" alignment-baseline="auto" style="fill: ${color}; opacity: 1;">${displayText}</text>
                    </svg>`;
        } else if (bubbleStyle == '3') {
            svg = `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="90" viewBox="0 0 25 17" fill="none" style="color: ${color}; opacity: 1;">
                        <rect x="0.5" y="0.5" width="24" height="16" rx="2.5" ry="2.5" stroke="currentColor" style="stroke: ${color}; stroke-opacity: 0.5; stroke-width: 1px; stroke-linejoin: round; fill: ${tccolor}; fill-opacity: 0.5;"></rect>
                        <text x="12.5" y="12" text-anchor="middle" alignment-baseline="auto" font-size="10" fill="currentColor" font-family="Arial, sans-serif" font-weight="500" style="fill: ${color}; opacity: 1;">${displayText}</text>
                    </svg>`;
        } else if (bubbleStyle == '4') {
            svg = `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="90" viewBox="0 0 25 17" fill="none" style="color:${color}; opacity: 1;">
                        <rect x="0.5" y="0.5" width="24" height="16" rx="8.5" ry="8.5" stroke="currentColor" style="stroke: ${color}; stroke-opacity: 0.5; stroke-width: 1px; stroke-linejoin: round; fill: ${tccolor}; fill-opacity: 0.5;"></rect>
                        <text x="12.5" y="12" text-anchor="middle" alignment-baseline="auto" font-size="10" fill="currentColor" font-family="Arial, sans-serif" font-weight="500" style="fill: ${color}; opacity: 1;">${displayText}</text>
                    </svg>`;
        } else if (bubbleStyle == '5') {
            displayText = number > 99 ? "99" : number.toString();
            svg = `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="90" viewBox="0 0 25 17" fill="none" style="color: ${color}; opacity: 1;">
                        <circle cx="12.5" cy="8.5" r="8" stroke="currentColor" style="stroke: ${color}; stroke-opacity: 0.5; stroke-width: 1px; stroke-linejoin: round; fill: ${tccolor}; fill-opacity: 0.5;"></circle>
                        <text x="13" y="12" text-anchor="middle" alignment-baseline="auto" font-size="10" fill="currentColor" font-family="Arial, sans-serif" font-weight="500" style="fill: ${color}; opacity: 1;">${displayText}</text>
                    </svg>`;
        } else {
            svg = `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="90" viewBox="0 0 25 17" fill="none" style="color: ${color}; opacity: 1;">
                <path d="M24 14.5v-12a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v7.528a2 2 0 0 1-.211.894l-2.065 4.13a1 1 0 0 0 .894 1.448H22a2 2 0 0 0 2-2z" stroke="currentColor" style="stroke: ${color}; stroke-opacity: 0.5; stroke-width: 1px; stroke-linejoin: round; fill: ${tccolor}; fill-opacity: 0.5;"></path>
                <text x="13.5" y="12" text-anchor="middle" alignment-baseline="auto" font-size="10" fill="currentColor" font-family="Arial, sans-serif" font-weight="500" style="fill: ${color}; opacity: 1;">${displayText}</text>
            </svg>`;
        }
        var encodedSvg = this.java.base64Encode(svg);
        return 'data:image/svg+xml;base64,' + encodedSvg + ',{"js":"showCmt(\'' + encodedUrl + '\', \'' + sources + '\')","style":"text"}';
    }


function cleanHTML(html) {
    let result = html
        .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, "")
        .replace(/<div class="tt-title"[^>]*>[\s\S]*?<\/div>/gi, "")
        .replace(/<(?!\/?p\b|\/?img\b)[^>]+>/gi, "");
    result = result.replace(/<\/?p[^>]*>/g, "\n");
    return result.replace(/\n+/g, "\n").trim();
}


function getBaseUrl(url) {
    if (!url) {
        return null;
    }
    url = String(url);
    if (url.match(/https?:\/\//i)) {
        var index = url.indexOf("/", 9);
        return index == -1 ? url : url.substring(0, index);
    }
    return null;
}

function isIPv4Address(ip) {
    ip = String(ip);
    let parts = ip.split(".");
    if (parts.length !== 4) return false;

    for (let part of parts) {
        if (!/^\d+$/.test(part)) return false; // 必须是数字
        if (part.length > 1 && part[0] === "0") return false; // 禁止前导零
        let num = parseInt(part, 10);
        if (num < 0 || num > 255) return false; // 范围检查
    }
    return true;
}

function isIPv6Address(ip) {
    ip = String(ip);
    // 处理双冒号（最多出现一次）
    if (ip.includes(":::")) return false;
    let doubleColonCount = (ip.match(/::/g) || []).length;
    if (doubleColonCount > 1) return false;

    // 分割成组
    let groups = ip.split(":");
    let validGroupCount = 8;
    let actualGroupCount = groups.filter((g) => g !== "").length;

    // 验证组数
    if (doubleColonCount === 1) {
        if (actualGroupCount > validGroupCount - 1) return false;
    } else {
        if (groups.length !== validGroupCount) return false;
    }

    // 验证每组内容
    for (let group of groups) {
        if (group === "") continue; // 跳过空组（双冒号部分）
        if (!/^[0-9a-fA-F]{1,4}$/.test(group)) return false; // 1-4位十六进制
    }
    return true;
}

function isIPAddress(input) {
    return isIPv4Address(input) || isIPv6Address(input);
}

function getSessionId(cookieString) {
    const match = cookieString.match(/sessionid=([^;]+)/);
    return match ? match[1] : null;
}

function getKey(key) {
    let parts = key.split(";");
    for (let part of parts) {
        if (part.includes("qttoken")) {
            return part.split("=")[1];
        }
    }
    return "";
}

function getFanqieCookie() {
    const {
        cookie
    } = this;
    try {
        return String(cookie.getCookie('fanqienovel.com') || java.getCookie('fanqienovel.com') || '');
    } catch (e) {
        return '';
    }
}


function paraForiOS(html, sources) {
    return html.replace(
        /<p>(.*?)(?:<comment ident="([^"]*)" count="([^"]*)" \/>)?<\/p>/g,
        function(match, text, url, count) {
            if (url && count) {
                const encodedUrl = url.replace(/&/g, '&amp;');
                return `<span rs-native>${text}<comment count="${count}" onPress="java.showReadingBrowser('${encodedUrl}','${sources}段评')"></span>`;
            } else {
                return `<span rs-native>${text}</span>`;
            }
        }
    );
}

